#!/usr/bin/env node
/**
 * Bundles three.core.js into a single IIFE and writes it to
 * src/utils/threeBundle.generated.ts as a string constant.
 *
 * Why: the standalone HTML export must work offline. The old exporter pulled
 * three.js r128 from cdnjs, so an exported book was an empty frame without
 * network. Bundling the same Three.js version the app itself uses (0.186)
 * also removes the version drift between reader and export.
 *
 * Runs automatically via the `prebuild` script.
 */
import { build } from 'esbuild';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const projectRoot = resolve(here, '..');

const result = await build({
  stdin: {
    contents: `export * from 'three';`,
    resolveDir: projectRoot,
    loader: 'js'
  },
  bundle: true,
  format: 'iife',
  globalName: 'THREE',
  minify: true,
  target: 'es2020',
  write: false,
  logLevel: 'warning'
});

const bundled = result.outputFiles[0].text;
if (!bundled.includes('THREE')) {
  throw new Error('esbuild output does not define THREE — bundle failed');
}

const outDir = resolve(projectRoot, 'src/utils');
mkdirSync(outDir, { recursive: true });

const outFile = resolve(outDir, 'threeBundle.generated.ts');
writeFileSync(
  outFile,
  `/* AUTO-GENERATED by scripts/build-three-bundle.mjs — do not edit.
 * Inlined Three.js build used by the standalone HTML exporter so exported
 * books work without network access. Regenerate with: npm run build:three
 */
export const THREE_BUNDLE_JS = ${JSON.stringify(bundled)};
`,
  'utf8'
);

const kb = (bundled.length / 1024).toFixed(0);
console.log(`three bundle written: src/utils/threeBundle.generated.ts (${kb} kB)`);
